#!/usr/bin/env node

/**
 * Plank-join checker: scans implementation directories for @planks and
 * @planks-provisional annotations and cross-references them against
 * step-definition patterns. Exits non-zero when a behaviour-bearing seam
 * has no plank, a plank matches no pattern, or a provisional plank names
 * a scenario that lost its @captain tag.
 *
 * Greenfield: no step definitions exist yet, so the check validates
 * annotation form only and reports the absence of patterns.
 */

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = process.cwd();
const IMPL_DIR = join(ROOT, 'js');
const SPECS_DIR = join(ROOT, 'features');

function walk(dir) {
  const results = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) results.push(...walk(full));
    else if (full.endsWith('.js')) results.push(full);
  }
  return results;
}

function readSpecs(dir) {
  const text = readFileSync(dir, 'utf8');
  return text;
}

// Gather step-definition patterns from features/support/
const stepPatterns = [];
const supportDir = join(SPECS_DIR, 'support');
try {
  for (const f of readdirSync(supportDir)) {
    if (!f.endsWith('.js') && !f.endsWith('.ts')) continue;
    const src = readFileSync(join(supportDir, f), 'utf8');
    const matches = src.matchAll(/(?:Given|When|Then)\(\s*\/([^/]+)\/|(?:Given|When|Then)\(\s*['"]([^'"]+)['"]/g);
    for (const m of matches) {
      stepPatterns.push(m[1] || m[2]);
    }
  }
} catch {
  // No support dir yet; expected at greenfield.
}

// Gather @captain scenarios from specs
const captainScenarios = [];
try {
  for (const f of readdirSync(SPECS_DIR)) {
    if (!f.endsWith('.feature')) continue;
    const src = readSpecs(join(SPECS_DIR, f));
    const lines = src.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].includes('@captain')) {
        // Find the next Scenario line
        for (let j = i; j < Math.min(i + 5, lines.length); j++) {
          const m = lines[j].match(/^Scenario:\s*(.+)/);
          if (m) {
            captainScenarios.push({ file: f, name: m[1].trim() });
            break;
          }
        }
      }
    }
  }
} catch {
  // No specs yet.
}

// Scan implementation for plank annotations
let exitCode = 0;
const planks = [];

try {
  const files = walk(IMPL_DIR);
  for (const file of files) {
    const src = readFileSync(file, 'utf8');
    const rel = relative(ROOT, file);

    const plankMatches = src.matchAll(/@planks\(\s*["']([^"']+)["']\s*\)/g);
    for (const m of plankMatches) {
      const pattern = m[1];
      const found = stepPatterns.some(p => p === pattern);
      planks.push({ file: rel, type: '@planks', pattern, found });
      if (!found) {
        console.error(`STALE PLANK: ${rel} @planks("${pattern}") matches no step-definition pattern`);
        exitCode = 1;
      }
    }

    const provMatches = src.matchAll(/@planks-provisional\(\s*["']([^"']+)["']\s*\)/g);
    for (const m of provMatches) {
      const ref = m[1];
      const refFile = ref.split(':')[0];
      const refScenario = ref.split(':')[1];
      const found = captainScenarios.some(s => s.file === refFile && s.name === refScenario);
      planks.push({ file: rel, type: '@planks-provisional', ref, found });
      if (!found) {
        console.error(`STALE PROVISIONAL: ${rel} @planks-provisional("${ref}") - scenario not found or not @captain`);
        exitCode = 1;
      }
    }
  }
} catch (err) {
  if (err.code !== 'ENOENT') {
    console.error(`plank-join: ${err.message}`);
    exitCode = 1;
  }
}

// Report
if (planks.length === 0 && stepPatterns.length === 0) {
  console.log('plank-join: no planks and no step definitions (greenfield)');
} else {
  console.log(`plank-join: ${planks.length} planks, ${stepPatterns.length} step patterns, ${captainScenarios.length} @captain scenarios`);
  for (const p of planks) {
    const status = p.found ? 'OK' : 'MISSING';
    console.log(`  ${status} ${p.file} ${p.type} ${p.pattern || p.ref}`);
  }
}

process.exit(exitCode);

